SELECT * FROM ydsz_wiki_file_acl
WHERE file_node_id = #{fileNodeId} AND grantee_type = #{granteeType}
AND grantee_id = #{granteeId} AND deleted = 0

SELECT DISTINCT a.* FROM ydsz_wiki_file_acl a
WHERE a.deleted = 0 AND a.file_node_id = #{fileNodeId}
AND (
    (a.grantee_type = 'user' AND a.grantee_id = #{userId})

        OR (a.grantee_type = 'role' AND a.grantee_id IN

            #{roleId}
        )

)
